 8	    public static int[][] shortestPaths(int[][] graph) {
 9	        int vertexCount = Matrices.requireSquare(graph, "Graph matrix");
10	        int[][] distances = Matrices.copyOf(graph);
11	
12	        for (int via = 0; via < vertexCount; via++) {
13	            for (int from = 0; from < vertexCount; from++) {
14	                for (int to = 0; to < vertexCount; to++) {
15	                    relax(distances, from, via, to);
16	                }
17	            }
18	        }
19	
20	        return distances;
21	    }
