24	        Matrices.requireSquare(distances, "Distance matrix");
25	
26	        for (int index = 0; index < distances.length; index++) {
27	            if (distances[index][index] < 0) {
28	                return true;
29	            }
30	        }
31	
32	        return false;
33	    }
