39	    private static void relax(int[][] distances, int from, int via, int to) {
40	        if (!canRelax(distances, from, via, to)) {
41	            return;
42	        }
43	
44	        int candidateDistance = pathDistanceThrough(distances, from, via, to);
45	        if (candidateDistance < distances[from][to]) {
46	            distances[from][to] = candidateDistance;
47	        }
48	    }
